"""Fulfilment endpoints for the warehouse."""

from __future__ import annotations

from typing import Any

from orders.application.errors import Conflict, OrderNotFound, ProductNotFound
from orders.application.fulfilment_service import FulfilmentService
from orders.controllers.http import (InvalidRequest, Response, bad_request, conflict, not_found,
                                     require_non_negative_int, require_positive_int, require_str)


class FulfilmentController:
    def __init__(self, service: FulfilmentService) -> None:
        self._service = service

    def handle_restock(self, request: dict[str, Any]) -> Response:
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)
        try:
            on_hand = self._service.restock(sku, quantity)
        except ProductNotFound:
            return not_found("product")
        return Response(200, {"sku": sku, "on_hand": on_hand})

    def handle_low_stock(self, threshold: Any) -> Response:
        try:
            threshold = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)
        products = self._service.low_stock(threshold)
        return Response(200, {"products": [{"sku": p.sku, "name": p.name, "on_hand": p.on_hand}
                                           for p in products]})

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            slip = self._service.packing_slip(order_id)
        except OrderNotFound:
            return not_found("order")
        except Conflict as exc:
            return conflict(exc)
        return Response(200, {
            "order_id": slip.order_id,
            "customer_name": slip.customer_name,
            "lines": [{"sku": l.sku, "name": l.name, "quantity": l.quantity} for l in slip.lines],
        })

def _place(shop):
    return shop.orders.handle_create(
        {"customer_id": "c1", "items": [{"sku": "PEN", "quantity": 3}, {"sku": "BOOK", "quantity": 1}]}
    ).body["order_id"]


def test_packing_slip(shop):
    order_id = _place(shop)
    res = shop.fulfilment.handle_packing_slip(order_id)
    assert res.status == 200
    assert res.body == {
        "order_id": order_id,
        "customer_name": "Ada",
        "lines": [{"sku": "PEN", "name": "Pen", "quantity": 3},
                  {"sku": "BOOK", "name": "Book", "quantity": 1}],
    }


def test_packing_slip_unknown_order(shop):
    res = shop.fulfilment.handle_packing_slip("nope")
    assert (res.status, res.body) == (404, {"error": "order not found"})


def test_packing_slip_cancelled_order(shop):
    order_id = _place(shop)
    shop.orders.handle_cancel(order_id)
    res = shop.fulfilment.handle_packing_slip(order_id)
    assert res.status == 409
    assert "error" in res.body


def test_low_stock_sorted_and_strict(shop):
    shop.catalog.handle_add_product({"sku": "ABC", "name": "Abc", "unit_price_cents": 1, "on_hand": 5})
    res = shop.fulfilment.handle_low_stock(50)
    assert res.status == 200
    assert res.body["products"] == [
        {"sku": "ABC", "name": "Abc", "on_hand": 5},
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
    ]
    assert shop.fulfilment.handle_low_stock(5).body == {"products": []}
    assert shop.fulfilment.handle_low_stock(0).body == {"products": []}


def test_restock_adds_stock_and_is_orderable(shop):
    res = shop.fulfilment.handle_restock({"sku": "LAMP", "quantity": 10})
    assert (res.status, res.body) == (200, {"sku": "LAMP", "on_hand": 15})
    order = shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "LAMP", "quantity": 15}]})
    assert order.status == 201


def test_restock_unknown_product(shop):
    res = shop.fulfilment.handle_restock({"sku": "NOPE", "quantity": 1})
    assert (res.status, res.body) == (404, {"error": "product not found"})


def test_restock_invalid_request_changes_nothing(shop):
    for bad in ({}, {"sku": "", "quantity": 1}, {"sku": 1, "quantity": 1}, {"sku": "LAMP"},
                {"sku": "LAMP", "quantity": 0}, {"sku": "LAMP", "quantity": -2},
                {"sku": "LAMP", "quantity": True}, {"sku": "LAMP", "quantity": "3"}):
        res = shop.fulfilment.handle_restock(bad)
        assert res.status == 400
        assert "error" in res.body
    assert shop.fulfilment.handle_low_stock(6).body["products"] == [{"sku": "LAMP", "name": "Lamp", "on_hand": 5}]


def test_low_stock_invalid_threshold(shop):
    for bad in (-1, True, "5", 1.5, None):
        res = shop.fulfilment.handle_low_stock(bad)
        assert res.status == 400
        assert "error" in res.body
